# -*- coding: utf-8 -*-
import json,pathlib
p=pathlib.Path(__file__).parent;d=json.loads((p/'candidate-peloponnesian-war-modern-da.json').read_text())
t={1:'Sådan foregik begravelsen denne vinter, som afsluttede krigens første år. Da sommeren begyndte, rykkede spartanerne og deres forbundsfæller igen ind i Attika med to tredjedele af deres styrker. De blev ledet af den spartanske konge Archidamos, Zeuxidamos’ søn, slog lejr og hærgede landet. Få dage efter deres ankomst begyndte pesten at vise sig blandt athenerne. Det hed sig, at den tidligere var brudt ud flere steder omkring Lemnos og andre steder, men ingen kunne huske en epidemi af så stort omfang og med så mange døde. Lægerne kunne i begyndelsen ikke hjælpe, fordi de ikke vidste, hvordan sygdommen skulle behandles. Tværtimod døde de særlig hyppigt, fordi de oftest var i kontakt med de syge. Heller ingen anden menneskelig kunnen kunne stille noget op. Bønner i templerne, orakler og lignende var lige så nytteløse. Til sidst opgav folk også dem, overvældet af katastrofen.',2:'Sygdommen begyndte efter sigende i de egne af Etiopien, der ligger syd for Egypten, og bredte sig derfra ned til Egypten og Libyen og til det meste af perserkongens rige. Den ramte pludselig Athen og angreb først befolkningen i Piræus. Det fik folk til at sige, at peloponneserne havde forgiftet cisternerne; der var nemlig endnu ingen brønde der. Senere viste den sig i selve byen, og da blev dødsfaldene langt hyppigere. Andre, både læger og lægfolk, må udtale sig om, hvor sygdommen kom fra, og hvad der kunne have fremkaldt en så voldsom forstyrrelse. Selv vil jeg beskrive dens forløb og de symptomer, som kan gøre det muligt at genkende den, hvis den en dag bryder ud igen. Det kan jeg gøre med større sikkerhed, fordi jeg selv havde sygdommen og så, hvordan den ramte andre.',3:'Alle var enige om, at dette år ellers havde været usædvanligt frit for sygdom. De få sygdomstilfælde, der forekom, udviklede sig alle til denne epidemi. Som regel begyndte den dog uden nogen synlig årsag. Mennesker, der var raske, fik pludselig voldsom hede i hovedet og røde, betændte øjne. Svælget og tungen blev blodrøde, og ånden fik en unaturlig, stinkende lugt. Så fulgte nysen og hæshed, og kort efter nåede smerterne brystet og fremkaldte en voldsom hoste. Når sygdommen nåede maven, kom den i oprør, og under store lidelser udtømtes galde af alle de slags, lægerne har navne for. De fleste fik også forgæves opkastningsbevægelser, som fremkaldte voldsomme kramper. Hos nogle ophørte de hurtigt, hos andre først langt senere. Udenpå føltes kroppen ikke særlig varm og så heller ikke bleg ud. Den var rødlig eller blålig og dækket af små blærer og sår. Men indvendig brændte den så stærkt, at den syge ikke kunne tåle selv det letteste tøj eller linned, men måtte ligge helt nøgen. Helst ville de kaste sig i koldt vand. Nogle, der lå uden pleje, styrtede sig faktisk ned i regnvandscisternerne, drevet af deres uudslukkelige tørst. Det gjorde dog ingen forskel, om de drak lidt eller meget. Desuden blev de hele tiden plaget af en ulidelig uro og manglende evne til at sove. Så længe sygdommen var på sit højeste, svandt kroppen ikke ind, men modstod dens angreb forbløffende godt. Når de fleste bukkede under for den indre betændelse på syvende eller ottende dag, havde de derfor stadig kræfter tilbage. Overlevede de dette stadium, gik sygdommen længere ned i tarmene, hvor den fremkaldte kraftig sårdannelse og voldsom diarré. Den svækkelse, der fulgte, førte som regel til døden. Sygdommen begyndte altså i hovedet og bredte sig derfra gennem hele kroppen. Selv når den ikke dræbte, satte den spor i kroppens yderste dele. Den angreb kønsdelene, fingrene og tæerne, og mange overlevede med tabet af dem; nogle mistede også øjnene. Andre havde helt mistet hukommelsen, da de først kom sig, og kunne hverken genkende sig selv eller deres venner.',4:'Sygdommen var svær at beskrive, og lidelserne næsten mere, end et menneske kunne udholde. Men især én ting viste, hvor forskellig den var fra almindelige sygdomme: De fugle og dyr, der plejer at æde menneskelig, rørte enten ikke ligene, selv om mange lå ubegravede, eller døde efter at have ædt af dem. Som tegn på det lagde man mærke til, at disse fugle faktisk forsvandt. De sås hverken ved ligene eller andre steder. Hos hundene, der levede tæt på mennesker, kunne man naturligvis tydeligst iagttage de virkninger, jeg har nævnt.',5:'Det var sygdommens almindelige træk, når man ser bort fra de mange særlige variationer i de enkelte tilfælde. Imens var byen fri for de sædvanlige sygdomme, eller også udviklede de tilfælde, der forekom, sig til denne sygdom. Nogle døde uden pleje, andre trods al tænkelig omsorg. Man fandt intet sikkert middel mod sygdommen; det, der hjalp én, skadede en anden. Hverken stærke eller svage mennesker kunne stå imod. Sygdommen rev dem alle med sig, selv om deres kost og pleje blev tilrettelagt med den største omhu. Det værste var den modløshed, der greb folk, så snart de mærkede, at de blev syge. De opgav straks håbet og mistede modstandskraften, så sygdommen lettere fik bugt med dem. Dertil kom det frygtelige syn af mennesker, der døde som får, fordi de havde smittet hinanden under plejen. Det var den vigtigste årsag til de mange dødsfald. Var de bange for at besøge hinanden, døde de syge uden hjælp; mange huse blev helt tømt for beboere, fordi ingen kunne pleje dem. Vovede de at besøge de syge, kostede det dem livet. Det ramte især dem, der satte en ære i at være gode mennesker. Af anstændighed sparede de ikke sig selv, men plejede deres venner, selv når familien til sidst var slidt op af de døendes klager og overvældet af katastrofen. De syge og døende fandt dog størst medfølelse hos dem, der var kommet sig. De kendte lidelserne af egen erfaring og frygtede ikke længere for sig selv. Ingen blev nemlig ramt to gange, i hvert fald ikke med dødelig udgang. Disse mennesker fik ikke alene andres lykønskninger; i deres glæde nærede de også det tomme håb, at de fremover var beskyttet mod enhver sygdom.',6:'Tilstrømningen fra landet til byen gjorde ulykken endnu værre, især for de nyankomne selv. Der var ingen boliger til dem, så i sommervarmen måtte de bo i kvælende hytter, hvor sygdommen dræbte uhæmmet. Døende mennesker lå oven på hinanden, og halvdøde vaklede rundt i gaderne og stimlede sammen ved alle vandposterne, drevet af tørst. Helligdommene, hvor folk havde slået sig ned, var også fulde af lig; de døde blev liggende, hvor de faldt. Da katastrofen overskred alle grænser, og ingen vidste, hvad der skulle blive af dem, mistede folk enhver respekt for både helligt og verdsligt. De hidtidige begravelsesskikke brød sammen, og man begravede de døde, som man bedst kunne. Mange havde allerede mistet så mange pårørende, at de manglede det nødvendige til en ordentlig begravelse og greb til skamløse midler. Nogle kom dem, der havde rejst et ligbål, i forkøbet, lagde deres egen døde på bålet og tændte det. Andre kastede det lig, de bar, oven på et, der allerede brændte, og gik deres vej.'}
x=[dict(language='modern-da',chapter=7,slot=s,before=d['chapters'][6]['paragraphs'][s-1],after=v,reason='Full historical plague account fluency repair; retain observed symptoms and reported uncertainty, no modern diagnosis. Slot6 own dead denotes dead relative, not living person’s own corpse.') for s,v in t.items()]
# Danish lig plural is invariant; avoid ambiguous compound spelling.
x[3]['after']=x[3]['after'].replace('æde menneskelig','æde lig af mennesker')
x.append(dict(language='modern-en',chapter=7,slot=6,before='they threw their own dead body on the stranger’s pyre',after='they threw their own dead relative’s body on someone else’s pyre',reason='Own dead means the corpse they are responsible for, not their own living body.'))
